-- PT109-S3-Q11. Batch 04.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch04$PT109-S3-Q11$batch04$ AND q.stimulus=$batch04$Some people claim that the reason herbs are not prescribed as drugs by licensed physicians is that the medical effectiveness of herbs is seriously in doubt. No drug can be offered for sale, however, unless it has regulatory-agency approval for medicinal use in specific illnesses or conditions. It costs about $200 million to get regulatory-agency approval for a drug, and only the holder of a patent can expect to recover such large expenses. Although methods of extracting particular substances from herbs can be patented, herbs themselves and their medicinal uses cannot be. Therefore, under the current system licensed physicians cannot recommend the medicinal use of herbs.$batch04$ AND q.prompt=$batch04$The argument depends on the assumption that$batch04$ AND q.correct_choice=$batch04$C$batch04$) THEN RAISE EXCEPTION 'Question changed: PT109-S3-Q11'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch04$PT109-S3-Q11$batch04$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT109-S3-Q11'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch04$PT109-S3-Q11$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch04$Conclusion$batch04$, $batch04$Under the current system, licensed physicians cannot recommend the medicinal use of herbs.$batch04$), (1, $batch04$Evidence$batch04$, $batch04$No drug can be sold without regulatory approval. Approval costs about $200 million, which only a patent holder can expect to recover. Herbs and their medicinal uses cannot be patented.$batch04$), (2, $batch04$Evaluate$batch04$, $batch04$The evidence shows herbs will not be *sold as drugs*. The conclusion is about what physicians can *recommend*. The argument needs a link between the two.$batch04$), (3, $batch04$Goal$batch04$, $batch04$A link: physicians can only recommend an herb if it is sold as a drug.$batch04$)) v(position,label,body) WHERE q.qid=$batch04$PT109-S3-Q11$batch04$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch04$A$batch04$, $batch04$The author argues against the idea that herbs are left out because they don't work. The author does not assume they are ineffective.$batch04$), ($batch04$B$batch04$, $batch04$When a substance is "properly" used is a different question from what physicians can recommend.$batch04$), ($batch04$C$batch04$, $batch04$Negate it: a physician *can* recommend an herb even when it is not sold as a drug. Then the patent and approval problems do not stop physicians from recommending herbs, and the conclusion falls apart.$batch04$), ($batch04$D$batch04$, $batch04$Other substances kept off the market for other reasons say nothing about herbs.$batch04$), ($batch04$E$batch04$, $batch04$The cost of medical care is never part of the argument.$batch04$)) v(letter,body) WHERE q.qid=$batch04$PT109-S3-Q11$batch04$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
